import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Entities","description":"","frontmatter":{"title":"Entities"},"headers":[],"relativePath":"api/reference/entities.md","filePath":"api/reference/entities.md"}`),a={name:`api/reference/entities.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="entities" tabindex="-1">Entities <a class="header-anchor" href="#entities" aria-label="Permalink to “Entities”">​</a></h1><div><p>Operations of the tag <strong>Entities</strong> implemented in this release. Generated from <code>api/openapi.yaml</code>; planned operations are not listed.</p><h2 id="getEntityHistory" tabindex="-1">Change history of an entity (SCR-026) <a class="header-anchor" href="#getEntityHistory" aria-label="Permalink to “Change history of an entity (SCR-026)”">​</a></h2><p><code>GET /entities/{id}/history</code> · <code>getEntityHistory</code></p><p>The versions of the entity, newest first (US-098, REQ-098, UC-14). Source: <code>entity_version_headers</code> with the changed fields from <code>entity_system_field_history</code> and <code>entity_property_value_history</code> (ADR-022). A version names its changed fields without values; values come from <code>getEntityVersion</code> and <code>compareEntityVersions</code>. Version 1 is the creation and has no changed fields.</p><p>A changed property the caller may not read (<code>role-restricted</code> without a read role, <code>connection-scoped</code> outside the caller&#39;s scope, REQ-160) is listed with <code>restricted: true</code>, or left out when every role of the caller is set to <code>hide</code> for the entity&#39;s metatype (<code>/admin/history-visibility</code>). A version whose fields are all left out is still listed. Holders of an override role read every field (REQ-128).</p><p><code>from</code> and <code>to</code> are inclusive; <code>from</code> after <code>to</code> answers 400 naming <code>from</code>. <code>actors</code> and <code>created</code> ignore the filters and the paging. Paging as in the delta list: send <code>nextCursor</code> with <code>page</code> + 1; a cursor of another query answers 400 <code>cursor</code>.</p><p><strong>Access</strong>: permission <code>entity:read</code></p><h3 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>yes</td><td>integer</td><td>Entity ID</td></tr><tr><td><code>from</code></td><td>query</td><td>no</td><td>string (date-time)</td><td>Earliest time of a listed version, inclusive (ISO 8601)</td></tr><tr><td><code>to</code></td><td>query</td><td>no</td><td>string (date-time)</td><td>Latest time of a listed version, inclusive (ISO 8601)</td></tr><tr><td><code>actorId</code></td><td>query</td><td>no</td><td>integer (int64)</td><td>Only the versions made by this person (<code>persons.id</code>)</td></tr><tr><td><code>page</code></td><td>query</td><td>no</td><td>integer</td><td>–</td></tr><tr><td><code>pageSize</code></td><td>query</td><td>no</td><td>integer</td><td>–</td></tr><tr><td><code>cursor</code></td><td>query</td><td>no</td><td>string</td><td>The <code>nextCursor</code> of the previous page, sent together with <code>page</code> set to that page&#39;s number + 1 (REQ-071). The page then starts after the last row of the previous one instead of skipping rows. The cursor is valid only for the same query (catalog, columns or view, sort, join modes, filters, page size) and only until the backend restarts or the catalog changes; otherwise the query is answered with 400 <code>cursor</code> and the client repeats it without the cursor.</td></tr></tbody></table><h3 id="responses" tabindex="-1">Responses <a class="header-anchor" href="#responses" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>Version history</td><td>–</td></tr><tr><td>400</td><td>Invalid filter, page size or cursor, named in <code>invalidFields</code></td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code> and <code>POST /me/password/suggestion</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Entity not found</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="getEntityVersion" tabindex="-1">Complete state of a version (SCR-026) <a class="header-anchor" href="#getEntityVersion" aria-label="Permalink to “Complete state of a version (SCR-026)”">​</a></h2><p><code>GET /entities/{id}/versions/{version}</code> · <code>getEntityVersion</code></p><p>The complete state of a version of the entity (US-100, REQ-100, UC-14): the system fields and the properties mapped to the entity&#39;s metatype at the time of the version (effective date on or before it), including empty ones, plus every property that had a value then. The state is reconstructed from the history tables (ADR-022); nothing is stored per version.</p><p>Versions are immutable: <code>PUT</code> and <code>DELETE</code> on this path answer 405 with <code>Allow: GET</code>.</p><p>A property the caller may not read is listed with <code>restricted: true</code> and no value, or left out by the history visibility, as in <code>getEntityHistory</code>. A value read only through an override role is audited as <code>property-override-access</code> (channel <code>history</code>).</p><p><strong>Access</strong>: permission <code>entity:read</code></p><h3 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>yes</td><td>integer</td><td>Entity ID</td></tr><tr><td><code>version</code></td><td>path</td><td>yes</td><td>integer</td><td>Version number</td></tr></tbody></table><h3 id="responses-1" tabindex="-1">Responses <a class="header-anchor" href="#responses-1" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>State of the version</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code> and <code>POST /me/password/suggestion</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Entity or version not found</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="compareEntityVersions" tabindex="-1">Field-by-field diff of two versions (SCR-026) <a class="header-anchor" href="#compareEntityVersions" aria-label="Permalink to “Field-by-field diff of two versions (SCR-026)”">​</a></h2><p><code>GET /entities/{id}/diff</code> · <code>compareEntityVersions</code></p><p>The fields whose value differs between the state of version <code>from</code> and the state of version <code>to</code> (US-099, REQ-099, UC-14): a net diff, so a field changed and changed back between them is not listed. The diff of a single version N is <code>from=N-1&amp;to=N</code>. <code>from</code> must be at least 1 and before <code>to</code>, otherwise 400 naming <code>from</code>; a version that does not exist answers 404.</p><p>Values the caller may not read are redacted or left out as in <code>getEntityVersion</code>.</p><p><strong>Access</strong>: permission <code>entity:read</code></p><h3 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>yes</td><td>integer</td><td>Entity ID</td></tr><tr><td><code>from</code></td><td>query</td><td>yes</td><td>integer</td><td>Earlier version</td></tr><tr><td><code>to</code></td><td>query</td><td>yes</td><td>integer</td><td>Later version</td></tr></tbody></table><h3 id="responses-2" tabindex="-1">Responses <a class="header-anchor" href="#responses-2" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>Diff of the two versions</td><td>–</td></tr><tr><td>400</td><td>Invalid version range, named in <code>invalidFields</code></td><td>–</td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code> and <code>POST /me/password/suggestion</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Entity or version not found</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="previewEntityRestore" tabindex="-1">Preview of a restore (SCR-027, UC-15) <a class="header-anchor" href="#previewEntityRestore" aria-label="Permalink to “Preview of a restore (SCR-027, UC-15)”">​</a></h2><p><code>GET /entities/{id}/restore</code> · <code>previewEntityRestore</code></p><p>What <code>restoreEntity</code> would do with the same target version (US-101 AC2, REQ-101): the current version and every field whose current value differs from the target version, with both values and whether it would be restored. A field is not restored when the caller may not write it (<code>write-protected</code>, REQ-162), when it is no longer mapped to the metatype (<code>not-mapped</code>) or when the current definition no longer accepts the target value (<code>invalid-value</code>, UC-15 E1). Mandatory and recommended properties that would be empty are warnings, never errors.</p><p>A value the caller may not read is redacted (REQ-101 AC5, REQ-160); a property hidden for the caller&#39;s roles is left out, and a value read through an override role is audited as <code>property-override-access</code> (channel <code>history</code>). Changes nothing.</p><p><strong>Access</strong>: permission <code>entity:write</code>, <code>entity:restore</code></p><h3 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>yes</td><td>integer</td><td>Entity ID</td></tr><tr><td><code>targetVersion</code></td><td>query</td><td>yes</td><td>integer</td><td>At least 1 and before the current version; otherwise 400 naming <code>targetVersion</code></td></tr></tbody></table><h3 id="responses-3" tabindex="-1">Responses <a class="header-anchor" href="#responses-3" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>The preview</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code> and <code>POST /me/password/suggestion</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Entity not found, or the target version is after the current version</td><td>–</td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table><h2 id="restoreEntity" tabindex="-1">Restore entity (SCR-027, UC-15) <a class="header-anchor" href="#restoreEntity" aria-label="Permalink to “Restore entity (SCR-027, UC-15)”">​</a></h2><p><code>POST /entities/{id}/restore</code> · <code>restoreEntity</code></p><p>Restores an entity in full to an earlier version (US-101, US-102, US-103, REQ-101 to REQ-103). Name, description, the logical flag and every restorable property get the values of the target version; a property empty in the target version is removed. The ID, the metatype, the endpoints of a connection and the creation fields never change. Fields are classified as in <code>previewEntityRestore</code>; fields not restored keep their current value and are listed in <code>notRestored</code>.</p><p>The restore writes one new version with <code>restoredFromVersion</code> and the reason; the version before it stays unchanged in the history as the state before the restore (ADR-022). An empty mandatory property is afterwards marked as missing. Entity, version and the audit event <code>entity.restored</code> are written in one transaction.</p><p><code>If-Match</code> with the current version is required: 428 without it, 412 <code>stale-version</code> when the entity changed meanwhile. A restore whose restorable fields all have their target value already gives 422 <code>urn:oea:problem:nothing-to-restore</code>.</p><p><strong>Access</strong>: permission <code>entity:write</code>, <code>entity:restore</code></p><h3 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>In</th><th>Required</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>path</td><td>yes</td><td>integer</td><td>Entity ID</td></tr><tr><td><code>If-Match</code></td><td>header</td><td>yes</td><td>string</td><td><code>ETag</code> of the version the client has read (<code>&quot;&lt;version&gt;&quot;</code>). A different version gives 412 <code>stale-version</code> and changes nothing; a missing header gives 428.</td></tr></tbody></table><h3 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to “Request body”">​</a></h3><ul><li><code>application/json</code>: RestoreRequest</li></ul><h3 id="responses-4" tabindex="-1">Responses <a class="header-anchor" href="#responses-4" aria-label="Permalink to “Responses”">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Description</th><th>Problem types</th></tr></thead><tbody><tr><td>200</td><td>Entity restored</td><td>–</td></tr><tr><td>400</td><td>The request does not meet the contract: a malformed body, a missing required field or parameter, a wrong type or format, or a value outside the limits of the schema (problem type <code>urn:oea:problem:validation-failed</code> unless the operation names another). Operations that answer such requests with 422 instead declare it in their own description.</td><td><code>urn:oea:problem:validation-failed</code></td></tr><tr><td>401</td><td>Not authenticated (missing, expired or revoked credentials or session). When a previously valid session or refresh token was presented and has ended, the header <code>OEA-Purge-Local-Data: session-ended</code> is set and the problem <code>type</code> is <code>urn:oea:problem:session-ended</code>.</td><td><code>urn:oea:problem:session-ended</code></td></tr><tr><td>403</td><td>Authenticated, but a permission declared in <code>x-oea-authorization</code> is missing, a separation-of-duties rule forbids the action (e.g. self-administration, SoD-1), or a privileged role is not effective because the session lacks a second factor (SoD-8). The problem body is generic and does not reveal the missing permission. A session created with a temporary password answers every operation except <code>GET /me</code>, the logout, <code>POST /me/password</code> and <code>POST /me/password/suggestion</code> with problem type <code>urn:oea:problem:password-change-required</code> (REQ-173 AC2). A session that must enroll a second factor answers every operation except <code>GET /me</code>, the logout, <code>GET /me/second-factors</code> and the TOTP and passkey enrollment with problem type <code>urn:oea:problem:second-factor-enrollment-required</code> (US-031 AC2). If the principal holds no effective role at all, the header <code>OEA-Purge-Local-Data: access-revoked</code> is set.</td><td><code>urn:oea:problem:password-change-required</code>, <code>urn:oea:problem:second-factor-enrollment-required</code></td></tr><tr><td>404</td><td>Entity not found, or the target version is after the current version</td><td>–</td></tr><tr><td>412</td><td><code>If-Match</code> does not name the current version of the element: someone else changed it meanwhile (problem type <code>urn:oea:problem:stale-version</code>, extension <code>currentVersion</code>). Nothing is changed.</td><td><code>urn:oea:problem:stale-version</code></td></tr><tr><td>413</td><td>Request body larger than the configured limit (problem type <code>urn:oea:problem:request-too-large</code>, REQ-186); nothing is processed. The limits are configurable by the operator – 1 MB by default, 10 MB for the entity batch.</td><td><code>urn:oea:problem:request-too-large</code></td></tr><tr><td>422</td><td>Nothing to restore (<code>urn:oea:problem:nothing-to-restore</code>); nothing is changed</td><td><code>urn:oea:problem:nothing-to-restore</code></td></tr><tr><td>428</td><td>The operation requires <code>If-Match</code> with the version the client has read (problem type <code>urn:oea:problem:precondition-required</code>). Nothing is changed.</td><td><code>urn:oea:problem:precondition-required</code></td></tr><tr><td>429</td><td>Rate limit or throttling exceeded (REQ-186, REQ-168), problem type <code>urn:oea:problem:too-many-requests</code>; <code>Retry-After</code> gives the seconds until the next request is accepted. Nothing was processed.</td><td><code>urn:oea:problem:too-many-requests</code></td></tr></tbody></table></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};